import pandas as pd
import seaborn as sns
import matplotlib.pyplot as plt
import os

# 1. Load the AI-Scored Dataset
# This file is generated by ml_engine/fraud_model.py
DATA_PATH = "ai_scored_forensic_dataset.csv"

def run_density_visualization():
    print("📊 Generating Forensic Density JointPlot...")
    
    try:
        df = pd.read_csv(DATA_PATH)
    except FileNotFoundError:
        print(f"❌ Error: {DATA_PATH} not found. Run the ML model first.")
        return

    # 2. Set Visual Theme (Matching your original style)
    sns.set_theme(style="whitegrid")
    plt.figure(figsize=(12, 8))

    # 3. Reconciled JointPlot Logic
    # We plot Word Count vs Sentiment, but color by the AI's 'fraud_risk_status'
    # This visually proves why the Isolation Forest flagged certain companies.
    g = sns.jointplot(
        data=df,
        x="word_count", 
        y="sentiment_score",
        hue="fraud_risk_status",
        palette={"CRITICAL ANOMALY": "#e74c3c", "NORMAL": "#2ecc71"},
        kind="scatter",
        height=8,
        marginal_kws=dict(fill=True)
    )

    # 4. Add Clear Forensic Labels
    g.fig.suptitle("Forensic Triangulation: SEC Obfuscation vs. AI Risk Scoring", y=1.02, fontsize=16)
    g.set_axis_labels("Disclosure Density (Word Count)", "Management Sentiment Score", fontsize=12)

    # 5. Save the Output for the Capstone Presentation
    output_dir = "analysis/plots"
    os.makedirs(output_dir, exist_ok=True)
    save_path = f"{output_dir}/forensic_density_matrix.png"
    
    plt.savefig(save_path, bbox_inches='tight')
    print(f"✅ Success! JointPlot saved to: {save_path}")
    
    # Optional: Show plot during manual execution
    # plt.show()

if __name__ == "__main__":
    run_density_visualization()